import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"04 · iOS","description":"iOS already has real glass, so the iOS side is deliberately thin.","frontmatter":{"description":"iOS already has real glass, so the iOS side is deliberately thin.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/04-ios"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/04-ios"}],["meta",{"property":"og:title","content":"04 · iOS · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"iOS already has real glass, so the iOS side is deliberately thin."}],["meta",{"name":"twitter:title","content":"04 · iOS · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"iOS already has real glass, so the iOS side is deliberately thin."}]]},"headers":[],"relativePath":"architecture/04-ios.md","filePath":"architecture/04-ios.md"}'),d={name:"architecture/04-ios.md"};function s(r,e,n,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="_04-·-ios" tabindex="-1">04 · iOS <a class="header-anchor" href="#_04-·-ios" aria-label="Permalink to &quot;04 · iOS&quot;">​</a></h1><p>iOS already has real glass, so the iOS side is deliberately thin.</p><table tabindex="0"><thead><tr><th>iOS</th><th>Effect</th><th>Tint</th><th>Lighting</th><th>Interactive</th></tr></thead><tbody><tr><td>26+</td><td><code>UIGlassEffect</code> (<code>.regular</code> / <code>.clear</code> from <code>appearance</code>)</td><td><code>glass.tintColor</code> (tint × tintOpacity)</td><td>system</td><td><code>glass.interactive</code></td></tr><tr><td>15–25</td><td><code>UIBlurEffect</code> system material (picked from <code>blurRadius</code>)</td><td>tint view inside the effect</td><td><code>CAGradientLayer</code> sheen along <code>lightAngle</code></td><td>JS scale (button)</td></tr></tbody></table><p><code>blurRadius</code> → material (iOS 15–25):</p><table tabindex="0"><thead><tr><th>blurRadius (dp)</th><th>Material</th></tr></thead><tbody><tr><td>≤ 6, or <code>appearance=&quot;clear&quot;</code></td><td><code>systemUltraThinMaterial</code></td></tr><tr><td>≤ 14</td><td><code>systemThinMaterial</code></td></tr><tr><td>≤ 26</td><td><code>systemMaterial</code></td></tr><tr><td>&gt; 26</td><td><code>systemThickMaterial</code></td></tr></tbody></table><h2 id="shader-mode-iosrenderer-shader" tabindex="-1">Shader mode (<code>iosRenderer=&quot;shader&quot;</code>) <a class="header-anchor" href="#shader-mode-iosrenderer-shader" aria-label="Permalink to &quot;Shader mode (\`iosRenderer=&quot;shader&quot;\`)&quot;">​</a></h2><p><code>LGShaderRenderer</code> is the iOS twin of <code>RenderNodeGlassRenderer</code>. Each display-link frame it captures the backdrop with <code>renderInContext</code> (half resolution when blur ≥ 8px), skips the GPU if the pixels are unchanged, blurs with <code>MPSImageGaussianBlur</code>, and runs a Metal port of <code>GlassShaderSource.kt</code> that also draws the tint and border. Keep steps 1–7 in sync with the AGSL.</p><p><code>GlassBackdrop</code> stays a plain <code>View</code>; it carries <code>nativeID=&quot;LiquidGlassBackdrop:&lt;id&gt;&quot;</code> and glass finds it by walking the window. A backdrop containing the glass is skipped. If Metal or the backdrop is missing, it stays on system glass.</p><p>Limits: <code>renderInContext</code> runs on the main thread for every glass view, so this mode costs more than system glass and has not been profiled on a real device. It does not capture video or other layers that bypass Core Animation rendering. <code>transitionDuration</code> does not animate in this mode, and <code>motionLighting</code> is not supported.</p><h2 id="view-structure" tabindex="-1">View structure <a class="header-anchor" href="#view-structure" aria-label="Permalink to &quot;View structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiquidGlassViewComponentView (self)</span></span>
<span class="line"><span> ├─ UIVisualEffectView  _effectView     (glass / blur, border, radius)</span></span>
<span class="line"><span> │    └─ contentView: _tintView + _sheenLayer (pre-26)</span></span>
<span class="line"><span> ├─ UIView              _fallbackView   (reduce transparency)</span></span>
<span class="line"><span> └─ LGChildContainerView _childContainer   ← React children mount HERE</span></span></code></pre></div><p>Children are mounted into <code>_childContainer</code> (overriding <code>mountChildComponentView</code>) because <code>RCTViewComponentView</code> checks child indexes on unmount. Putting glass layers in the same container would break those checks. The container returns <code>nil</code> from <code>hitTest</code> for empty space, so touches still resolve to the glass component view.</p><h2 id="ignored-on-ios-by-design" tabindex="-1">Ignored on iOS (by design) <a class="header-anchor" href="#ignored-on-ios-by-design" aria-label="Permalink to &quot;Ignored on iOS (by design)&quot;">​</a></h2><p>With the default <code>iosRenderer=&quot;system&quot;</code>: <code>refraction</code>, <code>distortion</code>, <code>chromaticAberration</code>, <code>edgeWidth</code>, <code>quality</code>, <code>motionLighting</code>, <code>backdropId</code>. The system owns those decisions. On iOS 26+ <code>blur</code>, <code>intensity</code>, <code>illumination</code> and <code>lightAngle</code> are also ignored.</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p><code>reduceTransparency</code> prop <strong>or</strong> the system setting shows the opaque <code>_fallbackView</code>. The view listens to <code>UIAccessibilityReduceTransparencyStatusDidChangeNotification</code> and updates live. Effect changes animate with <code>transitionDuration</code> unless the system Reduce Motion setting is on.</p><h2 id="build-requirement" tabindex="-1">Build requirement <a class="header-anchor" href="#build-requirement" aria-label="Permalink to &quot;Build requirement&quot;">​</a></h2><p>iOS 26 glass needs Xcode 26 (the <code>UIGlassEffect</code> code is behind <code>__IPHONE_26_0</code> compile guards). Older Xcode builds still work and use materials.</p>`,18)])])}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
